import { defineCollection, reference } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';
import { TOPIC_SLUGS } from './data/topics';
import { GROUP_IDS } from './data/tool-groups';

// Frontmatter convention (enforced by this schema — unknown keys are silently
// stripped by Zod, so do NOT add ones like `slug`, `excerpt`, `ogTitle`,
// `ogDescription`, `canonicalURL`, or `author`: they are ignored, and canonical
// + OG are generated by BaseHead.astro). Include `updatedDate` only when a post
// is genuinely revised on a later day than it was published — otherwise omit it
// (the layout hides a same-day "Updated", and article JSON-LD supplies its own
// datePublished/dateModified).
const blog = defineCollection({
	// Load Markdown and MDX files in the `src/content/blog/` directory.
	loader: glob({ base: './src/content/blog', pattern: '**/*.{md,mdx}' }),
	// Type-check frontmatter using a schema
	schema: ({ image }) =>
		z.object({
			title: z.string(),
			// Optional keyword-first title for the HTML <title>/SEO (falls back to title).
			seoTitle: z.string().optional(),
			// Optional CTR-tuned meta description (falls back to description, which
			// is also the on-page subtitle).
			seoDescription: z.string().optional(),
			// Post-specific OG image path (public/), falls back to the branded default.
			ogImage: z.string().optional(),
			description: z.string(),
			// Transform string to Date object
			pubDate: z.coerce.date(),
			updatedDate: z.coerce.date().optional(),
			heroImage: z.optional(image()),
			tags: z.array(z.string()).default([]),
			// Primary topic hub this post is filed under. Optional (drafts may omit
			// it), but when present must be one of the defined topic slugs — the
			// single source of truth for the /topics/ system.
			category: z.enum(TOPIC_SLUGS).optional(),
			draft: z.boolean().default(false),
			// When true, the post supplies its own article JSON-LD (e.g. TechArticle),
			// so BaseHead suppresses its generic Article to avoid duplicate schema.
			hasCustomSchema: z.boolean().default(false),
		}),
});

const projects = defineCollection({
	loader: glob({ base: './src/content/projects', pattern: '**/*.{md,mdx}' }),
	schema: ({ image }) =>
		z.object({
			title: z.string(),
			problem: z.string(),
			order: z.number(),
			featured: z.boolean().default(false),
			role: z.string().optional(),
			timeframe: z.string().optional(),
			tech: z.array(z.string()).default([]),
			// External links only when real — omit otherwise (no placeholders).
			liveUrl: z.string().url().optional(),
			repoUrl: z.string().url().optional(),
			highlights: z.array(z.string()).default([]),
			// Real numbers only. Left empty until verified figures exist.
			metrics: z.array(z.object({ value: z.string(), label: z.string() })).default([]),
			heroImage: z.optional(image()),
			draft: z.boolean().default(false),
		}),
});

// Developer Tools Hub (TOOLS_ROADMAP.md §9.3). One MDX per tool: frontmatter is
// the registry entry (hub card, menu, chaining, JSON-LD); the body is the
// tool's written guide. Only `status: live` entries produce pages, cards or
// links anywhere — drafts are invisible (zero dead UI).
const tools = defineCollection({
	loader: glob({ base: './src/content/tools', pattern: '**/*.{md,mdx}' }),
	schema: z
		.object({
			title: z.string(),
			seoTitle: z.string().max(60).optional(),
			description: z.string(),
			seoDescription: z.string().max(160).optional(),
			tier: z.enum(['signature', 'utility']),
			group: z.enum(GROUP_IDS),
			status: z.enum(['draft', 'live']).default('draft'),
			order: z.number().default(100),
			featured: z.boolean().default(false),
			pubDate: z.coerce.date(),
			updatedDate: z.coerce.date().optional(),
			keywords: z.array(z.string()).default([]),
			versions: z.array(z.string()).default([]),
			relatedPosts: z.array(reference('blog')).default([]),
			relatedTopic: z.enum(TOPIC_SLUGS).optional(),
			nextTools: z.array(reference('tools')).max(4).default([]),
			serviceCta: z.enum(['jobs-audit', 'scaling', 'postgres-review']).optional(),
			adsEligible: z.literal(false).default(false), // stays false until the Phase 3 gate (§15)
			shareable: z.boolean().default(true),
			worker: z.boolean().default(false),
			newUntil: z.coerce.date().optional(),
			faq: z.array(z.object({ q: z.string(), a: z.string() })).default([]),
		})
		.refine((t) => t.tier === 'signature' || !t.serviceCta, { message: 'serviceCta is signature-only' }),
});

export const collections = { blog, projects, tools };
